function getLookerAiTranslation(key, lang) {
    return (lookeraiTranslations[lang] && lookeraiTranslations[lang][key]) ||
           (lookeraiTranslations.en && lookeraiTranslations.en[key]) || null;
}

function applyLookerAiTranslations(lang) {
    let count = 0;
    document.querySelectorAll("[data-i18n]").forEach(el => {
        const key = el.getAttribute("data-i18n");
        if (key && (key.startsWith("review.looker-ai.") || key.startsWith("review.common."))) {
            const translation = getLookerAiTranslation(key, lang);
            if (translation) { el.textContent = translation; count++; }
        }
    });
    console.log(`Applied ${count} looker-ai translations`);
}

window.addEventListener("languageChanged", e => setTimeout(() => applyLookerAiTranslations(e.detail.language), 200));

if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => applyLookerAiTranslations(window.i18n?.getCurrentLanguage() || "en"));
} else {
    applyLookerAiTranslations(window.i18n?.getCurrentLanguage() || "en");
}
